from app import parse_settings

def test_parse_settings():
    assert parse_settings('a=1; b = two') == {'a': '1', 'b': 'two'}
    assert parse_settings('a=1;;') == {'a': '1'}
    assert parse_settings('flag; c=3') == {'c': '3'}
    assert parse_settings('') == {}
    assert parse_settings('url=x=y') == {'url': 'x=y'}
